//! Slint's Rust API, on a runtime that shows the user interface with Windows.UI.Composition.
//!
//! The API matches the upstream `slint` crate 1.19, so that code generated by the unmodified
//! `slint-build` and [`slint!`] compiles against it, with this exception:
//!
//! - There is no backend or renderer selection. [`platform`] keeps the types that the
//!   `Window` API uses, but custom platforms can't be installed. Upstream's features that
//!   choose a backend or a renderer are accepted and do nothing.

#![warn(missing_docs)]
#![deny(unsafe_code)]

extern crate alloc;

/// Upstream's compiler, unmodified, as upstream re-exports it.
pub use slint_macros::slint;

