pub mod wuc;

/// Runs `f` with this thread's context, creating the Win32 host on first use.
fn with_context<R>(f: impl FnOnce(&i_slint_core::SlintContext) -> R) -> Result<R, PlatformError> {
    let mut platform_created = false;
    let result = i_slint_core::with_global_context(
        || {
            let platform = alloc::boxed::Box::new(i_slint_core::host::Platform::new()?);
            platform_created = true;
            Ok(platform)
        },
        f,
    );

    #[cfg(feature = "mcp")]
    if result.is_ok() && platform_created {
        init_testing_backends();
    }
    #[cfg(not(feature = "mcp"))]
    let _ = platform_created;

    result
}

/// Starts the MCP server if the `mcp` feature is enabled, as upstream's backend selector does
/// once it has created the platform. The server listens when `SLINT_MCP_PORT` is set.
#[cfg(feature = "mcp")]
fn init_testing_backends() {
    if let Err(e) = i_slint_backend_testing::mcp_server::init() {
        i_slint_core::debug_log!("MCP server init failed: {e:?}");
    }
}

/// Enters the main event loop, which shows the windows and reacts to user input.
///
/// It runs until the last window is closed and the last visible system tray icon is hidden,
/// or until [`quit_event_loop()`] is called.
pub fn run_event_loop() -> Result<(), PlatformError> {
    with_context(|ctx| ctx.run_event_loop())?
}

/// Like [`run_event_loop()`], but keeps running when no window or tray icon is visible,
/// until [`quit_event_loop()`] is called.
pub fn run_event_loop_until_quit() -> Result<(), PlatformError> {
    with_context(|ctx| {
        #[allow(deprecated)]
        ctx.platform().set_event_loop_quit_on_last_window_closed(false);
        ctx.run_event_loop()
    })?
}

/// Spawns a [`Future`](core::future::Future) to execute in the Slint event loop.
///
/// Call it from the thread that runs the event loop, typically from a UI callback.
/// From another thread, call it from a closure passed to [`invoke_from_event_loop()`].
pub fn spawn_local<F: core::future::Future + 'static>(
    fut: F,
) -> Result<JoinHandle<F::Output>, EventLoopError> {
    with_context(|ctx| ctx.spawn_local(fut)).map_err(|_| EventLoopError::NoEventLoopProvider)?
}

/// Includes the code that `slint_build::compile` generated in the build script.
#[macro_export]
macro_rules! include_modules {
    () => {
        include!(env!("SLINT_INCLUDE_GENERATED"));
    };
}

/// Initializes translations when using the `gettext` feature.
///
/// Translations are found at `<dirname>/<locale>/LC_MESSAGES/<crate>.mo`.
#[cfg(feature = "gettext")]
#[macro_export]
macro_rules! init_translations {
    ($dirname:expr) => {
        $crate::private_unstable_api::init_translations(env!("CARGO_PKG_NAME"), $dirname);
    };
}

/// Forces all the strings that are translated with `@tr(...)` to be re-evaluated.
///
/// Call it after changing the language at run time when translating with gettext or a custom
/// translator. Bundled translations don't need it.
pub fn update_all_translations() {
    i_slint_core::translations::mark_all_translations_dirty();
}

/// The types that the `Window` API uses to talk about the windowing system.
pub mod platform {
    pub use i_slint_core::platform::{
        Clipboard, EventLoopProxy, Key, PlatformError, PointerEventButton, SetPlatformError,
        WindowEvent, WindowEventDispatchResult, duration_until_next_timer_update,
        update_timers_and_animations,
    };
    pub use i_slint_core::platform::{LayoutConstraints, WindowAdapter, WindowProperties};
}

/// The enums and structs of the Slint language.
pub mod language {
    macro_rules! export_builtin_structs {
        ($(
            $(#[$attr:meta])*
            $vis:vis struct $Name:ident {
                $( $(#[$field_attr:meta])* $field:ident : $field_type:ty $(= $field_default:expr)?, )*
            }
        )*) => {
            $( #[allow(unused_imports)] $vis use i_slint_core::items::$Name; )*
        };
    }

    i_slint_common::for_each_builtin_structs!(export_builtin_structs);

    macro_rules! export_builtin_enums {
        ($(
            $(#[$attr:meta])*
            $vis:vis enum $Name:ident { $($_body:tt)* }
        )*) => {
            $( #[allow(unused_imports)] $vis use i_slint_core::items::$Name; )*
        };
    }

    i_slint_common::for_each_enums!(export_builtin_enums);
}

